WITH ep AS (SELECT p.*, (p.statut='valide' AND (p.type_paiement<>'cheque' OR p.statut_cheque='encaisse')) effective FROM paiements p),
alloc AS (SELECT a.id_transaction, SUM(a.quantite) allocated, SUM(a.quantite_livree) delivered FROM egg_sale_allocations a GROUP BY a.id_transaction),
money_mov AS (SELECT id_paiement, COUNT(*) n, SUM(CASE WHEN type_mouvement='ENTREE' THEN montant ELSE -montant END) signed_amount FROM (SELECT id_paiement,type_mouvement,montant FROM caisse WHERE statut='active' AND id_paiement IS NOT NULL UNION ALL SELECT id_paiement,type_mouvement,montant FROM mouvements_bancaires WHERE statut='active' AND id_paiement IS NOT NULL)m GROUP BY id_paiement),
account_check AS (SELECT b.id_compte,b.solde_actuel,COALESCE(SUM(CASE WHEN m.statut='active' THEN CASE WHEN m.type_mouvement='ENTREE' THEN m.montant ELSE -m.montant END ELSE 0 END),0) ledger_balance FROM comptes_bancaires b LEFT JOIN mouvements_bancaires m ON m.id_compte=b.id_compte GROUP BY b.id_compte,b.solde_actuel)
SELECT jsonb_build_object(
'captured_at',now(),
'counts',jsonb_build_object('transactions',(SELECT count(*) FROM transactions),'active_transactions',(SELECT count(*) FROM transactions WHERE est_actif),'payments',(SELECT count(*) FROM ep),'canceled_payments',(SELECT count(*) FROM ep WHERE statut='annule'),'effective_payments',(SELECT count(*) FROM ep WHERE effective),'cash_movements',(SELECT count(*) FROM caisse),'bank_movements',(SELECT count(*) FROM mouvements_bancaires),'stock_movements',(SELECT count(*) FROM mouvements_stock),'allocations',(SELECT count(*) FROM egg_sale_allocations),'financial_corrections',(SELECT count(*) FROM corrections_financieres),'transaction_audits',(SELECT count(*) FROM transactions_audit),'credit_letters',(SELECT count(*) FROM lettres_credit)),
'money',jsonb_build_object('effective_paid',(SELECT COALESCE(SUM(montant),0) FROM ep WHERE effective),'cash_active_excluding_cessions',(SELECT COALESCE(SUM(CASE WHEN type_mouvement='ENTREE' THEN montant ELSE -montant END),0) FROM caisse WHERE statut='active' AND id_cession IS NULL),'cash_view',(SELECT solde_actuel FROM vue_solde_caisse LIMIT 1),'cash_latest_snapshot',(SELECT solde FROM caisse_solde_historique ORDER BY date_snapshot DESC,id_historique DESC LIMIT 1)),
'issues',jsonb_build_object(
'nonvoid_payments_on_canceled_transactions',(SELECT count(*) FROM ep p JOIN transactions t USING(id_transaction) WHERE NOT t.est_actif AND p.statut<>'annule'),
'active_payment_before_transaction',(SELECT count(*) FROM ep p JOIN transactions t USING(id_transaction) WHERE t.est_actif AND p.statut<>'annule' AND p.date_paiement<t.date_transaction),
'canceled_payment_before_transaction',(SELECT count(*) FROM ep p JOIN transactions t USING(id_transaction) WHERE p.statut='annule' AND p.date_paiement<t.date_transaction),
'invalid_due_dates',(SELECT count(*) FROM transactions WHERE date_echeance<date_transaction),
'effective_payment_movement_count',(SELECT count(*) FROM ep p JOIN transactions t USING(id_transaction) LEFT JOIN money_mov m USING(id_paiement) WHERE t.est_actif AND p.effective AND COALESCE(m.n,0)<>1),
'ineffective_payment_with_active_movement',(SELECT count(*) FROM ep p JOIN money_mov m USING(id_paiement) WHERE NOT p.effective AND m.n>0),
'effective_payment_movement_amount_or_direction',(SELECT count(*) FROM ep p JOIN transactions t USING(id_transaction) JOIN money_mov m USING(id_paiement) WHERE p.effective AND t.est_actif AND m.n=1 AND ABS(m.signed_amount-CASE WHEN t.id_client IS NOT NULL THEN p.montant ELSE -p.montant END)>0.01),
'cash_payment_transaction_mismatch',(SELECT count(*) FROM caisse c JOIN ep p USING(id_paiement) WHERE c.statut='active' AND c.id_transaction IS NOT NULL AND c.id_transaction<>p.id_transaction),
'active_charge_movement_mismatch',(SELECT count(*) FROM charges ch LEFT JOIN (SELECT id_charge,count(*) n,sum(CASE WHEN type_mouvement='SORTIE' THEN montant ELSE -montant END) amount FROM (SELECT id_charge,montant,type_mouvement FROM caisse WHERE statut='active' AND id_charge IS NOT NULL UNION ALL SELECT id_charge,montant,type_mouvement FROM mouvements_bancaires WHERE statut='active' AND id_charge IS NOT NULL)s GROUP BY id_charge)m USING(id_charge) WHERE ch.statut='active' AND (COALESCE(m.n,0)<>1 OR abs(m.amount-ch.montant)>0.01)),
'bank_balance_mismatches',(SELECT count(*) FROM account_check WHERE ABS(solde_actuel-ledger_balance)>0.01),
'duplicate_active_lc_payments',(SELECT count(*) FROM (SELECT id_lc FROM ep WHERE id_lc IS NOT NULL AND statut<>'annule' GROUP BY id_lc HAVING count(*)>1)s),
'negative_general_inventory',(SELECT count(*) FROM (SELECT id_produit FROM mouvements_stock GROUP BY id_produit HAVING SUM(quantite_delta)<0)s),
'duplicate_active_stock_sources',(SELECT count(*) FROM (SELECT source_type,source_id,type_mouvement,id_produit FROM mouvements_stock WHERE id_mouvement_inverse IS NULL AND source_id IS NOT NULL GROUP BY source_type,source_id,type_mouvement,id_produit HAVING count(*)>1)s),
'invalid_allocation_bounds',(SELECT count(*) FROM egg_sale_allocations WHERE quantite<=0 OR quantite_livree<0 OR quantite_livree>quantite),
'deferred_allocations_exceed_order',(SELECT count(*) FROM transactions t JOIN alloc a USING(id_transaction) WHERE t.est_actif AND t.est_promesse AND a.allocated+t.quantite_annulee>t.quantite),
'production_overallocated',(SELECT count(*) FROM (SELECT p.id_production FROM productions p JOIN egg_sale_allocations a USING(id_production) JOIN transactions t USING(id_transaction) WHERE t.est_actif GROUP BY p.id_production,p.nombre_oeufs HAVING SUM(a.quantite)>p.nombre_oeufs)s),
'ordinary_sale_uses_future_production',(SELECT count(DISTINCT t.id_transaction) FROM transactions t JOIN egg_sale_allocations a USING(id_transaction) JOIN productions p ON p.id_production=a.id_production WHERE t.est_actif AND NOT t.est_promesse AND p.date_production>t.date_transaction)
),
'legacy',jsonb_build_object('active_unlinked_ordinary_sales',(SELECT count(*) FROM transactions t WHERE t.est_actif AND t.id_client IS NOT NULL AND NOT t.est_promesse AND t.id_production IS NULL AND NOT EXISTS(SELECT 1 FROM egg_sale_allocations a WHERE a.id_transaction=t.id_transaction))),
'accounts',(SELECT jsonb_agg(to_jsonb(a)) FROM account_check a),
'deferred_totals',(SELECT jsonb_build_object('orders',count(*),'ordered',COALESCE(sum(t.quantite),0),'allocated',COALESCE(sum(a.allocated),0),'delivered',COALESCE(sum(a.delivered),0),'closed',COALESCE(sum(t.quantite_annulee),0)) FROM transactions t LEFT JOIN alloc a USING(id_transaction) WHERE t.est_actif AND t.est_promesse)
) AS reconciliation_baseline;
